const dados = $input.first().json;
const ontem = new Date();
ontem.setDate(ontem.getDate() - 1);
const dataFormatada = ontem.toLocaleDateString('pt-BR');

const taxaConclusao = dados.total_pedidos > 0
  ? ((dados.pedidos_concluidos / dados.total_pedidos) * 100).toFixed(1)
  : 0;

const receitaFormatada = new Intl.NumberFormat('pt-BR', {
  style: 'currency',
  currency: 'BRL'
}).format(dados.receita_total || 0);

const html = `
<h2>Relatório Diário — ${dataFormatada}</h2>
<table border="1" cellpadding="8" style="border-collapse:collapse;">
  <tr><th>Métrica</th><th>Valor</th></tr>
  <tr><td>Total de Pedidos</td><td><strong>${dados.total_pedidos}</strong></td></tr>
  <tr><td>Concluídos</td><td style="color:green">${dados.pedidos_concluidos}</td></tr>
  <tr><td>Cancelados</td><td style="color:red">${dados.pedidos_cancelados}</td></tr>
  <tr><td>Pendentes</td><td style="color:orange">${dados.pedidos_pendentes}</td></tr>
  <tr><td>Taxa de Conclusão</td><td>${taxaConclusao}%</td></tr>
  <tr><td>Receita Total</td><td><strong>${receitaFormatada}</strong></td></tr>
  <tr><td>Clientes Ativos</td><td>${dados.clientes_ativos}</td></tr>
</table>
`;

return [{ json: { ...dados, html_relatorio: html, data_referencia: dataFormatada } }];
